import{z as l,x as s,o as e,c as d,q as t,j as A,D as a,d as B,s as o,S as i,b as r}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"战时金融","description":"","frontmatter":{"title":"战时金融","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mh-wartime-finance.md","filePath":"econ/mh-wartime-finance.md","lastUpdated":1791413859000}'),p={name:"econ/mh-wartime-finance.md"};function c(C,E,h,D,m,f){const n=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=t('<h1 id="战时金融" tabindex="-1">战时金融 <a class="header-anchor" href="#战时金融" aria-label="Permalink to &quot;战时金融&quot;">​</a></h1><div class="epigraph"><p>摧毁一个社会既有秩序最隐蔽、也最难挽回的路径，是败坏它的通货。</p><footer>—— 据 Keynes, The Economic Consequences of the Peace, 1919 转述列宁之言整理</footer></div><p><a href="/econ/mh-gold-standard-operation">上一课</a>把金本位写成一份「战时停兑、战后按旧平价重返」的规则合同，豁免条款正是为战争预留的。本课写战争如何动用这份豁免：军费瞬间放大，税收按年征收、举债按市场胃口供给，缺口只剩印钞一条腿。停兑授权印钞，印钞改写物价，战后用一代人的紧缩把承诺赎回。本课程由此进入货币史的断裂段：每一块本位都是在这里被撬开的。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>战争把支出曲线垂直拉起，而财政的另外两根支柱都是慢变量：加税要立法、要征管，发债要有人信你会还在。第三根支柱是铸币：央行资产端吃进国债，负债端吐出货币，即时可得。缺口是把三者的边界写成一条财政约束——当第一、二根柱子撑不住时，货币承诺必然让位。Sargent 与 Wallace 的「不愉快的算术」把这点说尽：财政定了基调，货币在余下的空间里选择时点，而不是选择方向。</p><p><span class="marginnote">直觉类比：战争像一夜刷爆的账单——加税是「自己去加班挣钱」，发债是「找朋友借钱」，都是慢功夫；印钞则是「直接透支未来」，秒到账。停兑就是给这张卡解除额度限制，账单（通胀）稍后才到，但一定到。</span></p><h3 id="通货膨胀税的账" tabindex="-1">通货膨胀税的账 <a class="header-anchor" href="#通货膨胀税的账" aria-label="Permalink to &quot;通货膨胀税的账&quot;">​</a></h3><p>印钞的收入不是面额，而是每期按通胀稀释公众实际余额的所得：</p> \\[s \\;=\\; \\frac{\\pi}{1+\\pi}\\cdot\\frac{M}{P}, \\]<p>\\(\\pi\\) 越高、公众持有的实际余额 \\(\\frac{M}{P}\\) 越小，税基随税率收缩——这条拉弗曲线在<a href="/econ/seigniorage">通胀税与铸币税</a>已完整给出，本课只取它在战时的用途：停兑等于把这台机器全功率打开。</p><p><span class="marginnote">美国南北战争两次《法定货币法》（1862–1863）共发行 4.5 亿美元绿背券，无法兑金；1864 年夏 1 绿背美元跌到不足金平价的四成。英国 1797 年限制令停兑 24 年，1815 年战债已超过 GDP 的两倍。</span></p><p><span class="marginnote">数字实例：月通胀 \\(\\pi=2\\%\\) 时，\\(\\frac{\\pi}{1+\\pi}\\approx 2\\%\\)，政府每月大约征走公众持币实际价值的 2%；把 \\(\\pi\\) 抬到 10%，比例约 9%，但公众会同时把实际余额砍掉一大块——税率翻五倍，税基缩得更狠，收入未必更大。战时财政就是在这条曲线上找一个还坐得住的位置。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三个战时标本同构。其一，英国对拿破仑战争：1797 年限制令停止英格兰银行兑付，银行券对金升水流通，战后 1821 年按旧平价恢复兑付——中间是李嘉图参与的「金块论战」。其二，美国内战：绿背券以法定货币身份流通，金价与绿背价的黑市每日报价；1875 年《恢复铸兑法》定下日程，1879 年元旦按战前平价恢复兑付。其三，第一次大战：1914 年 8 月各国几乎同时停止金兑付——不是市场挤兑了金本位，是财政按住了它。</p><p>三案的共同工序是：停兑放开印钞 → 通胀税补上军费缺口 → 和平后以旧平价为复本目标 → 用紧缩与承诺赎回信誉。</p>',15)),(e(),A(i,null,{default:a(()=>[o(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20WAR%5B%22%E5%86%9B%E8%B4%B9%E5%9E%82%E7%9B%B4%E6%8B%89%E8%B5%B7%22%5D%20--%3E%20MIX%7B%22%E7%A8%8E%E4%B8%8E%E5%80%BA%E5%A4%9F%E4%B8%8D%E5%A4%9F%3F%22%7D%0A%20%20MIX%20--%3E%7C%E5%A4%9F%7C%20BOND%5B%22%E4%B8%BE%E5%80%BA%E4%B8%8E%E5%8A%A0%E7%A8%8E%EF%BC%8C%E6%89%BF%E8%AF%BA%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20MIX%20--%3E%7C%E4%B8%8D%E5%A4%9F%7C%20SUSP%5B%22%E5%81%9C%E5%85%91%EF%BC%8C%E6%8E%88%E6%9D%83%E5%8D%B0%E9%92%9E%22%5D%0A%20%20SUSP%20--%3E%20IT%5B%22%E9%80%9A%E8%B4%A7%E8%86%A8%E8%83%80%E7%A8%8E%E8%A1%A5%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20IT%20--%3E%20INFL%5B%22%E7%89%A9%E4%BB%B7%E4%B8%8A%E8%A1%8C%EF%BC%8C%E6%9C%AC%E5%B8%81%E5%AF%B9%E9%87%91%E8%B4%AC%E5%80%BC%22%5D%0A%20%20PEACE%5B%22%E5%92%8C%E5%B9%B3%EF%BC%9A%E5%A4%8D%E6%9C%AC%E7%9B%AE%E6%A0%87%E5%AE%9A%E4%B8%BA%E6%97%A7%E5%B9%B3%E4%BB%B7%22%5D%20--%3E%20DEFL%5B%22%E7%B4%A7%E7%BC%A9%E8%B5%8E%E5%9B%9E%E6%89%BF%E8%AF%BA%22%5D%0A%20%20DEFL%20--%3E%20RES%5B%22%E6%8C%89%E6%97%A7%E5%B9%B3%E4%BB%B7%E5%A4%8D%E5%85%91%EF%BC%8C%E4%BF%A1%E8%AA%89%E9%87%8D%E5%BB%BA%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=r("h2",{id:"机制",tabindex:"-1"},[B("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=r("p",null,"机制是「按旧平价重返」这个目标的双向作用：向前看，它使战时通胀被理解为一次性偏离，公众在贬值的纸币与金之间仍留着转换预期，货币没有当场作废；向后看，它要求战后真实紧缩——1821 年的英国在多年的物价回落里完成复兑，1879 年的美国靠 1870 年代的美元升值爬回平价。复本不是技术操作，是财政对货币的一次性认账。不这么做会错在哪：把停兑写成「金本位又一次失败」，就看不见失败的是财政，金本位只是被按住的承诺；同样，把 1879 年复本当成货币当局的手艺，就漏掉了 Friedman 与 Schwartz 强调的另一半——战后实际产出与价格的路径早已替兑换铺了路。",-1)),(e(),A(i,null,{default:a(()=>[o(n,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20LR%0A%20%20RULE%5B%22%E8%A7%84%E5%88%99%3A%20%E6%88%98%E5%90%8E%E6%8C%89%E6%97%A7%E5%B9%B3%E4%BB%B7%E5%A4%8D%E6%9C%AC%22%5D%20--%3E%20FWD%5B%22%E5%90%91%E5%89%8D%E7%9C%8B%3A%20%E6%88%98%E6%97%B6%E9%80%9A%E8%83%80%E6%98%AF%E4%B8%80%E6%AC%A1%E6%80%A7%E5%81%8F%E7%A6%BB%22%5D%0A%20%20FWD%20--%3E%20KEEP%5B%22%E5%85%AC%E4%BC%97%E4%BB%8D%E6%84%BF%E6%8C%81%E6%9C%89%E8%B4%AC%E5%80%BC%E7%BA%B8%E5%B8%81%2C%20%E7%AD%89%E5%BE%85%E5%85%91%E6%8D%A2%22%5D%0A%20%20RULE%20--%3E%20BWD%5B%22%E5%90%91%E5%90%8E%E7%9C%8B%3A%20%E6%88%98%E5%90%8E%E5%BF%85%E9%A1%BB%E7%9C%9F%E5%AE%9E%E7%B4%A7%E7%BC%A9%22%5D%0A%20%20BWD%20--%3E%20PAY%5B%22%E7%89%A9%E4%BB%B7%E5%9B%9E%E8%90%BD%E6%88%96%E7%BE%8E%E5%85%83%E5%8D%87%E5%80%BC%2C%20%E7%88%AC%E5%9B%9E%E5%B9%B3%E4%BB%B7%22%5D%0A%20%20PAY%20--%3E%20REDEEM%5B%221821%20%E8%8B%B1%E5%9B%BD%E4%B8%8E%201879%20%E7%BE%8E%E5%9B%BD%3A%20%E4%BF%A1%E8%AA%89%E8%B5%8E%E5%9B%9E%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">常见误区：初学者容易把 1821 或 1879 的复本读成「央行终于把汇率修好了」。实际上爬回平价靠的是战后一整代人的物价路径与财政认账，不是某一次精准操作；而且若没有「按旧平价重返」这句事先写好的承诺，战时纸币根本撑不到和平那一天。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课停在「复本成功」的标本；当财政缺口大到无法用温和通胀税覆盖、公众拒绝持有余额时，同一台机器会冲出拉弗曲线的顶点，那是下一课的恶性通胀。一战后的金汇兑本位与 1925 年英国的复本争论，归<a href="/econ/gold-standard-depression">金本位与大萧条</a>与<a href="/econ/bretton-woods-collapse">布雷顿森林与崩溃</a>；央行在停兑期的非常规角色见<a href="/econ/bm-lender-of-last-resort">最后贷款人</a>。战债货币化的现代版本是<a href="/econ/central-bank-balance-sheet">央行资产负债表</a>的题材，此处不重写。</p><p>后课默认：谈「财政主导」，就是这一课的机器转速盖过了货币规则。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>战时财政三支柱里，印钞是唯一即期可得的一根；停兑是它的授权书。</li><li>通胀税税基随税率收缩：温和时是收入，极端时是通往恶性通胀的斜坡。</li><li>「按旧平价重返」同时提供战前的持有信心与战后的紧缩义务。</li><li>停兑不是金本位的失败，是财政对它的使用；复本才是信誉的重新购买。</li><li>出处：Keynes 1919；Sargent and Wallace 1981；Friedman and Schwartz 1963；Bordo and Kydland 1995。</li></ul>',6))])}const _=l(p,[["render",c]]);export{u as __pageData,_ as default};
